CREATE OR REPLACE VIEW `vwenasarcotot` AS select `v`.`produttore` AS `produttore`,`v`.`montante` AS `montante`,`v`.`contributo` AS `contributo`,concat(if((least(`e`.`massimo`,`v`.`contributo`) = `e`.`massimo`),'+',''),if((greatest(`e`.`minimale`,`v`.`contributo`) = `e`.`minimale`),'-','')) AS `X`,least(`e`.`massimo`,greatest(`e`.`minimale`,`v`.`contributo`)) AS `imposta`,`v`.`montante` AS `firr`,`v`.`competenza` AS `competenza`,`e`.`enasarco` AS `enasarco` from (`vwenasarco` `v` left join `enasarcos` `e` on(((`e`.`competenza` = `v`.`competenza`) and (`e`.`enasarco` = `v`.`enasarco`)))) order by `v`.`competenza` desc,`v`.`produttore`
